const root = ($json.body && typeof $json.body === 'object') ? $json.body : ($json || {});
let oi = String(root.oi || '').trim();
let q = String(root.q || root.query || '').trim();
let action = String(root.action || 'search').toLowerCase();
const clientId = String(root.client_id || '').trim();
const clientName = String(root.client_name || root.name || '').trim();

if (!oi && /^support:(\d+)/i.test(clientId)) {
  oi = clientId.replace(/^support:/i, '');
}
const qDigits = q.replace(/\D/g, '');
if (!oi && qDigits.length >= 5 && /^[\d.\s-]+$/.test(q)) {
  oi = qDigits;
  action = 'select';
}
if (oi) {
  oi = oi.replace(/[^\d.]/g, '');
  if (oi && !oi.endsWith('.')) oi += '.';
}

const route = (action === 'select' || oi) ? 'select' : 'search';

return [{
  json: {
    oi,
    q,
    action,
    route,
    client_name: clientName,
    client_id: clientId
  }
}];

const meta = $('Normalizar OI').first().json;
const raw = $input.first().json;
let rows = raw;
if (rows && rows.data && Array.isArray(rows.data)) rows = rows.data;
if (!Array.isArray(rows)) rows = [];

function isActive(v) {
  if (v === true) return true;
  if (v === false) return false;
  const s = String(v || '').toUpperCase();
  return ['ATIVADO','ACTIVE','ATIVO','1','TRUE','SIM','YES'].includes(s);
}
function isMeli(row) {
  const label = String(row.integration || row.name || '').toUpperCase();
  const norm = label.replace(/[^A-Z0-9]/g, '');
  if (['MERCADOLIVRE','ML','MELI'].includes(norm)) return true;
  return label.includes('MERCADO') && label.includes('LIVRE');
}
function tokenFrom(row) {
  for (const k of ['api_key','apiKey','access_token','accessToken','token','value']) {
    const v = String(row[k] || '').trim();
    if (v) return v;
  }
  return '';
}

const oi = meta.oi || '';
const oiDigits = oi.replace(/\D/g, '');
if (!oiDigits) {
  return [{ json: { success: false, error: 'OI inválido ou ausente.' } }];
}
const clientId = `support:${oiDigits}`;
const name = (meta.client_name || '').trim() || `Cliente ${oiDigits}`;

let meliToken = '';
const integrations = [];
for (const row of rows) {
  if (!row || typeof row !== 'object') continue;
  const label = String(row.integration || '').trim();
  if (label && !integrations.includes(label)) integrations.push(label);
  if (isMeli(row) && isActive(row.active)) {
    const t = tokenFrom(row);
    if (t && !meliToken) meliToken = t;
  }
}

return [{
  json: {
    success: true,
    oi,
    client: {
      id: clientId,
      name,
      platform: name.replace(/[^A-Za-z0-9]/g, '').toUpperCase() || 'ANYMARKET',
      oi,
      source: 'support',
      has_ml: Boolean(meliToken),
      has_gumga: false,
      has_sku_webhook: true,
      has_meli_token_webhook: false,
      marketplaces: integrations,
      backoffice_api_ok: true
    },
    meli_token: meliToken
  }
}];

const raw = $input.first().json;
let rows = raw;
if (rows && rows.data && Array.isArray(rows.data)) rows = rows.data;
if (!Array.isArray(rows)) rows = [];

const seen = new Set();
const clients = [];
for (const row of rows) {
  if (!row || typeof row !== 'object') continue;
  const oiVal = String(row.hierarchyCode || row.id || '').trim();
  const digits = oiVal.replace(/\D/g, '');
  if (!digits) continue;
  const id = `support:${digits}`;
  if (seen.has(id)) continue;
  seen.add(id);
  clients.push({
    id,
    name: String(row.name || id).trim(),
    oi: oiVal.endsWith('.') ? oiVal : `${digits}.`,
    active: Boolean(row.active),
    source: 'support'
  });
}
clients.sort((a, b) => {
  if (a.active !== b.active) return a.active ? -1 : 1;
  return a.name.localeCompare(b.name, 'pt-BR');
});

return [{ json: { success: true, clients } }];
